# Reproduction of published numbers
#
# Run from the package root, after devtools::load_all() or
# library(OncoCohortSelect):
#   source("inst/reproduce/reproduce_published.R")
# Writes inst/reproduce/output/reproduce_published.csv and
# inst/reproduce/output/reproduce_published.md (generated, do not edit by hand).
#
# Judgments: PASS (agreement within the tolerance), EXPLAINED (not reproduced,
# with a registered reason), FAIL, INFO (reported without a judgment).

if (!exists("PosteriorProb")) library(OncoCohortSelect)
out_dir <- file.path("inst", "reproduce", "output")
dir.create(out_dir, showWarnings = FALSE, recursive = TRUE)

rows <- list()
add <- function(source, quantity, published, computed, tol, reason = "", info = FALSE) {
  diff <- abs(computed - published)
  judg <- if (info) {
    "INFO"
  } else if (!is.na(diff) && diff <= tol) {
    "PASS"
  } else if (nzchar(reason)) {
    "EXPLAINED"
  } else {
    "FAIL"
  }
  rows[[length(rows) + 1L]] <<- data.frame(source = source, quantity = quantity,
                                           published = published, computed = computed,
                                           abs_diff = diff, tolerance = tol,
                                           judgment = judg, reason = reason,
                                           stringsAsFactors = FALSE)
}

# ---- 1. Chakraborty et al. (2026), supplementary material, Section S.4 ----
# The R code of Section S.4 computes, for a dose and a control arm, the posterior
# probabilities P(Delta >= t) of two efficacy and five safety endpoints with
# beta-binomial models (posterior parameters from response rates and sample
# sizes), the admissibility and the benefit-risk score. Its printed output is
# "1, 0.46" (admissible; BR = 0.46).
src <- "Chakraborty et al. (2026), Section S.4"
ss_c <- 50
ss_d <- 45
r_c <- c(0.45, 0.36, 0, 0.37, 0.4, 0.45, 0.52)
r_d <- c(0.73, 0.53, 0, 0.45, 0.5, 0.42, 0.58)
cut <- c(0.20, 0.10, 0, 0.05, 0.10, 0.15, 0.20)
p_cut <- c(rep(0.30, 2), rep(0.95, 5))
pa <- c(0.67, 0.43, rep(0.5, 5))
pb <- c(1, 1, rep(0.5, 5))
p <- PosteriorProb("rate", a = pa + ss_d * r_d, b = pb + ss_d - ss_d * r_d, target = cut,
                   a.ref = pa + ss_c * r_c, b.ref = pb + ss_c - ss_c * r_c)
adm <- all(p[1:2] > p_cut[1:2]) && all(p[3:7] < p_cut[3:7])
br <- prod(p[1:2]) ^ (1 / 2) * prod(1 - p[3:7]) ^ (1 / 5)
add(src, "admissible (1 = yes)", 1, as.numeric(adm), 0)
add(src, "BR (published to 2 decimals)", 0.46, br, 0.005)
ep <- c("PFSrate", "ORR", "TRAEDT", "TRAEDC", "TRAEDR", "TRAEDD", "TRAEGR3+")
for (k in 1:7) {
  add(src, paste0("P(Delta >= t), ", ep[k], " (not printed in the article)"), NA, p[k],
      NA, info = TRUE)
}
# the same score from BenefitRisk()-style weights: efficacy and safety geometric means
add(src, "BR with weights 1/2 (efficacy) and 1/5 (safety)", 0.46,
    exp(sum(c(rep(1 / 2, 2), rep(1 / 5, 5)) * log(c(p[1:2], 1 - p[3:7])))), 0.005)

# ---- 2. Chakraborty et al. (2026), Table 7 ----
reason_t7 <- paste("The numbers of patients of arms C, D and F and the priors of the",
                   "application are not reported, so the posterior probabilities",
                   "cannot be recomputed from Table 5.")
for (x in list(c("criteria 1", 0.26, 0.50), c("criteria 2", 0.11, 0.34),
               c("criteria 3", 0.04, 0.20))) {
  add("Chakraborty et al. (2026), Table 7", paste0("BR(C, D), ", x[1]), as.numeric(x[2]),
      NA, 0.005, reason = reason_t7)
  add("Chakraborty et al. (2026), Table 7", paste0("BR(F, D), ", x[1]), as.numeric(x[3]),
      NA, 0.005, reason = reason_t7)
}

# ---- 3. Chakraborty et al. (2026), Table 2 ----
add("Chakraborty et al. (2026), Table 2", "admissibility boundaries for N = 50 per arm", NA,
    NA, NA, reason = paste("The control rates that determine the boundaries are not",
                           "reported."))

res <- do.call(rbind, rows)
utils::write.csv(res, file.path(out_dir, "reproduce_published.csv"), row.names = FALSE)
fmt <- function(x) ifelse(is.na(x), "", formatC(x, digits = 6, format = "g"))
md <- c("# Reproduction of published numbers", "",
        paste0("Generated by inst/reproduce/reproduce_published.R on ", Sys.Date(),
               " with OncoCohortSelect ", utils::packageVersion("OncoCohortSelect"), "."), "",
        paste0("Judgments: ", paste(names(table(res$judgment)), table(res$judgment),
                                    sep = " = ", collapse = ", "), "."), "",
        "| Source | Quantity | Published | Computed | Judgment | Reason |",
        "|---|---|---|---|---|---|",
        paste0("| ", res$source, " | ", res$quantity, " | ", fmt(res$published), " | ",
               fmt(res$computed), " | ", res$judgment, " | ", res$reason, " |"))
writeLines(md, file.path(out_dir, "reproduce_published.md"))
print(table(res$judgment))
if (any(res$judgment == "FAIL")) warning("Some published numbers were not reproduced.")
